css:
html,
body {
    width: 100%;
    height: 100%;
    margin: 0;
}

#Fun_Animated_Grid {
    --grid-size: 25vmin;
    --half-grid: calc(var(--grid-size) / 2);
    --primary-color: pink;
    --secondary-color: dodgerblue;
    --background-color: white;
    --animation-duration: 4000ms;
    --animation-timing: cubic-bezier(0.76, 0, 0.24, 1);

    width: 100%;
    min-height: 100vh;
    position: relative;
    overflow: hidden;

    background-color: var(--background-color);
    background-image:
        linear-gradient(45deg,
            var(--primary-color) 25%,
            transparent 25%),
        linear-gradient(-45deg,
            var(--primary-color) 25%,
            transparent 25%),
        linear-gradient(45deg,
            transparent 75%,
            var(--secondary-color) 75%),
        linear-gradient(-45deg,
            transparent 75%,
            var(--secondary-color) 75%);

    background-size: var(--grid-size) var(--grid-size);

    animation:
        gridColorChange var(--animation-duration) var(--animation-timing) infinite,
        gridPositionChange var(--animation-duration) var(--animation-timing) infinite;
}

#Fun_Animated_Grid h1 {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    margin: 0;
    padding: 2rem;
    font-family: cursive;
    font-size: clamp(2rem, 5vw, 4rem);
    text-align: center;
}

@keyframes gridColorChange {

    0%,
    25% {
        background-color: var(--background-color);
    }

    26%,
    50% {
        background-color: var(--primary-color);
    }

    51%,
    75% {
        background-color: var(--background-color);
    }

    76%,
    100% {
        background-color: var(--secondary-color);
    }
}

@keyframes gridPositionChange {
    0% {
        background-position:
            calc(var(--half-grid) * 1) calc(var(--half-grid) * 0),
            calc(var(--half-grid) * -1) calc(var(--half-grid) * 1),
            calc(var(--half-grid) * 1) calc(var(--half-grid) * -1),
            calc(var(--half-grid) * -1) calc(var(--half-grid) * 0);
    }

    25% {
        background-position:
            calc(var(--half-grid) * 1) calc(var(--half-grid) * 4),
            calc(var(--half-grid) * -1) calc(var(--half-grid) * 5),
            calc(var(--half-grid) * 1) calc(var(--half-grid) * 3),
            calc(var(--half-grid) * -1) calc(var(--half-grid) * 4);
    }

    50% {
        background-position:
            calc(var(--half-grid) * 3) calc(var(--half-grid) * 8),
            calc(var(--half-grid) * -3) calc(var(--half-grid) * 9),
            calc(var(--half-grid) * 2) calc(var(--half-grid) * 7),
            calc(var(--half-grid) * -2) calc(var(--half-grid) * 8);
    }

    75% {
        background-position:
            calc(var(--half-grid) * 3) calc(var(--half-grid) * 12),
            calc(var(--half-grid) * -3) calc(var(--half-grid) * 13),
            calc(var(--half-grid) * 2) calc(var(--half-grid) * 11),
            calc(var(--half-grid) * -2) calc(var(--half-grid) * 12);
    }

    100% {
        background-position:
            calc(var(--half-grid) * 6) calc(var(--half-grid) * 16),
            calc(var(--half-grid) * -5) calc(var(--half-grid) * 17),
            calc(var(--half-grid) * 5) calc(var(--half-grid) * 15),
            calc(var(--half-grid) * -5) calc(var(--half-grid) * 16);
    }
}

@media (prefers-reduced-motion: reduce) {
    #Fun_Animated_Grid {
        animation: none;
    }
}
